    row_bands = []
    start = 0
    for r in range(h):
        if all(v == 8 for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))

    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == 8 for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    # Record the color markers by their cell coordinates.
    markers = {}
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color not in (0, 8):
                        markers.setdefault(color, set()).add((ri, ci))

    # Each pair of aligned markers draws a segment, stopping at its endpoints.
    fills = {}
    for color, points in markers.items():
        by_row = {}
        by_col = {}
        for ri, ci in points:
            by_row.setdefault(ri, []).append(ci)
            by_col.setdefault(ci, []).append(ri)
        for ri, cols in by_row.items():
            if len(cols) >= 2:
                for ci in range(min(cols), max(cols) + 1):
                    fills.setdefault((ri, ci), set()).add(color)
        for ci, rows in by_col.items():
            if len(rows) >= 2:
                for ri in range(min(rows), max(rows) + 1):
                    fills.setdefault((ri, ci), set()).add(color)

    out = [row[:] for row in grid]
    for (ri, ci), colors in fills.items():
        r0, r1 = row_bands[ri]
        c0, c1 = col_bands[ci]
        color = next(iter(colors)) if len(colors) == 1 else 6
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color
    return out
